import re
files=["Picard_QuotScheme.tex","Picard_GrassmannianQuot.tex","Picard_FlatteningStratification.tex","Picard_SectionGradedRing.tex","Picard_LineBundleCoherence.tex","Picard_GrassmannianCells.tex"]
for fn in files:
    lines=open(fn,encoding='utf-8').read().split('\n')
    clean=[re.sub(r'(?<!\\)%.*','',l) for l in lines]
    c='\n'.join(clean)
    depth=0;extra=0
    for i,ch in enumerate(c):
        if ch=='{' and (i==0 or c[i-1]!='\\'): depth+=1
        elif ch=='}' and (i==0 or c[i-1]!='\\'):
            depth-=1
            if depth<0: extra+=1; depth=0
    stack=[];errs=[]
    for i,l in enumerate(clean,1):
        for m in re.finditer(r'\\begin\{([^}]*)\}',l): stack.append((m.group(1),i))
        for m in re.finditer(r'\\end\{([^}]*)\}',l):
            if stack and stack[-1][0]==m.group(1): stack.pop()
            else: errs.append((i,m.group(1)))
    print('%-40s depth=%d extraClose=%d envErrs=%s unclosed=%s math$=%s'%(fn,depth,extra,errs[:3],stack[:3],c.count('$')%2))
EOF
